import{_ as a,o as t,c as n,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const m=JSON.parse('{"title":"Lending-money source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/52-lending-money-profile.md","filePath":"reference/52-lending-money-profile.md","lastUpdated":1788593217000}'),r={name:"reference/52-lending-money-profile.md"};function o(s,e,d,l,c,h){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="lending-money-source-profile" tabindex="-1">Lending-money source profile <a class="header-anchor" href="#lending-money-source-profile" aria-label="Permalink to &quot;Lending-money source profile&quot;">​</a></h1><h2 id="authority-and-role" tabindex="-1">Authority and role <a class="header-anchor" href="#authority-and-role" aria-label="Permalink to &quot;Authority and role&quot;">​</a></h2><p>The <code>lending_money</code> activity follows B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter X, “Lending Money,” internal printed page 45 (physical PDF page 49 in the inspected 2020 Chistabo derivative). It is the lender or creditor side of making a loan. Borrowing, receiving repayment and investing capital are separate activities.</p><p>Raman says the otherwise prohibited stars are suitable for receiving money. That observation is documented but is not exposed as a repayment-receipt profile without its own complete crosswalk.</p><h2 id="exact-automated-gates" tabindex="-1">Exact automated gates <a class="header-anchor" href="#exact-automated-gates" aria-label="Permalink to &quot;Exact automated gates&quot;">​</a></h2><ul><li>Reject Krittika, Magha, Moola, Shatabhisha, Uttara Phalguni and Punarvasu. Raman&#39;s abbreviated “Uttara” is resolved as Uttara Phalguni, consistent with his naming convention elsewhere in the edition.</li><li>Reject the lender&#39;s Janma Nakshatra when supplied.</li><li>Reject Tuesday and Friday; admit the other five weekdays without inventing preference bonuses.</li><li>Reject Amavasya only when the weekday is Saturday. Neither all Saturdays nor every Amavasya is prohibited by this sentence.</li></ul><h2 id="chart-checks-and-independent-practice-conflict" tabindex="-1">Chart checks and independent-practice conflict <a class="header-anchor" href="#chart-checks-and-independent-practice-conflict" aria-label="Permalink to &quot;Chart checks and independent-practice conflict&quot;">​</a></h2><p>The Lagna and 7th lords should be harmonious, and Chandra in Vrischika is described as adverse for the lender. These remain manual prerequisites, so an automated result cannot receive <code>Excellent</code>.</p><p>Drik Panchang&#39;s current loan-giving methodology instead says not to lend on Wednesday. That directly differs from Raman, who excludes Tuesday and Friday and therefore admits Wednesday. The published-practice disagreement is stored as <code>muhurta.lending.drkpanchang_divergence</code>; the product follows its explicitly named Raman lineage rather than silently combining both.</p><h2 id="financial-safety" tabindex="-1">Financial safety <a class="header-anchor" href="#financial-safety" aria-label="Permalink to &quot;Financial safety&quot;">​</a></h2><p>Timing cannot establish creditworthiness, affordability, enforceability, repayment probability or investment safety. Credit assessment, documentation, interest and collateral law, concentration risk and qualified advice govern the decision.</p>',11)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
